package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the owner's telephone to E.164 form (see {@link OwnerTelephones}): strip
 * spaces, dashes and brackets; keep a leading '+' and country code when present, otherwise
 * assume country code '+61' and drop a single leading '0' from the national digits; require
 * 8 to 15 digits after the '+'. The E.164 value is stored back on the owner (so it is
 * persisted and returned); anything that cannot form a valid E.164 number escalates as a
 * 400 via {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val Owner owner) throws InvalidTelephoneException {
        String e164 = OwnerTelephones.toE164(owner.getTelephone());
        if (e164 == null) {
            throw new InvalidTelephoneException(
                    "Telephone cannot be formatted as a valid E.164 number "
                            + "(8 to 15 digits after the country code)");
        }
        owner.setTelephone(e164);
    }
}
=== NormalizeOwnerEmail ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Email is optional on an owner. When absent (null or blank) this step does nothing.
 * When present it must be a syntactically valid address, otherwise it escalates as a
 * 400 via {@link InvalidEmailException}. A valid address is stored back on the owner
 * lower-cased (so it is persisted and returned lower-cased).
 */
public class NormalizeOwnerEmail {

    /**
     * Pragmatic syntactic check: a non-empty local part, a single '@', then a domain
     * with at least one dot and no whitespace.
     */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val Owner owner) throws InvalidEmailException {
        String email = owner.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        String trimmed = email.trim();
        if (!EMAIL.matcher(trimmed).matches()) {
            throw new InvalidEmailException("Email must be a syntactically valid address");
        }
        owner.setEmail(trimmed.toLowerCase());
    }
}
=== RejectDuplicateTelephone ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;

/**
 * Rejects creating an owner whose E.164 telephone is already used by any other owner.
 * Runs after {@link NormalizeOwnerTelephone} (so the owner's telephone is already the E.164
 * value) and before {@link SaveOwner}. Each stored telephone is converted to E.164 through
 * {@link OwnerTelephones} before comparison, so a stored value in any format still collides.
 * A match on a different owner escalates as a 409 via {@link DuplicateTelephoneException}.
 */
public class RejectDuplicateTelephone {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        // The incoming owner's telephone is already E.164 (from NormalizeOwnerTelephone);
        // only the stored values (which may predate the pipeline) need converting to compare.
        String telephone = owner.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
                continue;
            }
            // A stored value that cannot form valid E.164 yields null, which never matches.
            if (telephone.equals(OwnerTelephones.toE164(existing.getTelephone()))) {
                throw new DuplicateTelephoneException(
                        "Telephone is already used by another owner");
            }
        }
    }
}
